// Des: Local purge: old raw files to trash once verified
// Flo: expire old trash days > move aged verified raw files to trash/<yyyymmdd>/ > at the high mark empty the trash and delete oldest verified files down to the low mark > nothing verified left? stuck, never delete > prune old log, outbox and dead rows
// I/O: data folder + local Db + Conf + clock (caller) > Lres; unverified files are never touched; dryz only counts
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const hash = @import("ut-hash-dedu.zig"); const civi = @import("ut-date-civi.zig");
const CF = .{ .dayz = 86400000, .gibi = 1 << 30, .hard = 95, .rawd = "raw", .tras = "trash" };
pub const Actl = enum { none, pruned, stuck };
pub const Lres = struct { act2: Actl = .none, used: u64 = 0, cap2: u64 = 0, aged: u32 = 0, pres: u32 = 0, byts: u64 = 0, tras: u32 = 0, logz: u32 = 0, outb: u32 = 0, dead: u32 = 0, plan: bool = false };
pub const Loca = struct { iozz: std.Io, dbzz: *sqli.Dbzz, dirz: []const u8, conf: cfgz.Conf, dryz: bool = false, capz: u64 = 0 };
const Item = struct { rela: []const u8, hexz: []const u8, size: u64, mtim: i64 };
fn lessItem(_: void, left: Item, rite: Item) bool { if (left.mtim != rite.mtim) return left.mtim < rite.mtim; return std.mem.lessThan(u8, left.rela, rite.rela); }
pub fn locaUsed(aren: std.mem.Allocator, iozz: std.Io, dirz: []const u8) !u64 { var dirx = std.Io.Dir.cwd().openDir(iozz, dirz, .{ .iterate = true }) catch return 0; defer dirx.close(iozz); var walk = try dirx.walk(aren); defer walk.deinit(); var tota: u64 = 0; while (try walk.next(iozz)) |entr| { if (entr.kind != .file) continue; const stat = entr.dir.statFile(iozz, entr.basename, .{}) catch continue; tota += stat.size; } return tota; }
pub fn fullChek(used: u64, capb: u64) bool { return used * 100 >= capb * CF.hard; }
pub fn locaFull(aren: std.mem.Allocator, iozz: std.Io, dirz: []const u8, conf: cfgz.Conf) !bool { return fullChek(try locaUsed(aren, iozz, dirz), @as(u64, conf.capz_disk_gbyt) * CF.gibi); }
fn scanRaws(self: *Loca, aren: std.mem.Allocator) ![]Item { const rawd = try std.fs.path.join(aren, &.{ self.dirz, CF.rawd }); var dirx = std.Io.Dir.cwd().openDir(self.iozz, rawd, .{ .iterate = true }) catch return &.{}; defer dirx.close(self.iozz); var walk = try dirx.walk(aren); defer walk.deinit(); var list: std.ArrayList(Item) = .empty; while (try walk.next(self.iozz)) |entr| { if (entr.kind != .file or !std.mem.endsWith(u8, entr.basename, ".gz")) continue; const stem = entr.basename[0 .. entr.basename.len - 3]; if (!hash.hashOkay(stem)) continue; const stat = entr.dir.statFile(self.iozz, entr.basename, .{}) catch continue; try list.append(aren, .{ .rela = try aren.dupe(u8, entr.path), .hexz = try aren.dupe(u8, stem), .size = stat.size, .mtim = stat.mtime.toMilliseconds() }); } std.mem.sort(Item, list.items, {}, lessItem); return list.toOwnedSlice(aren); }
fn iszzSafe(self: *Loca, hexz: []const u8) !bool { var stmt = try self.dbzz.prep("SELECT vfyz FROM pack WHERE hexz=?1;"); defer stmt.fini(); try stmt.bindText(1, hexz); if (!try stmt.step()) return false; return stmt.colzIntz(0) > 0 or !self.conf.purg_loca_veri; }
fn moveTras(self: *Loca, aren: std.mem.Allocator, item: Item, nowz: i64) !void { const cwdz = std.Io.Dir.cwd(); const oldp = try std.fs.path.join(aren, &.{ self.dirz, CF.rawd, item.rela }); if (self.conf.purg_tras_days == 0) { try cwdz.deleteFile(self.iozz, oldp); return; } var dbuf: [8]u8 = undefined; const newp = try std.fs.path.join(aren, &.{ self.dirz, CF.tras, civi.civiDayz(nowz, &dbuf), item.rela }); if (std.fs.path.dirname(newp)) |dirn| try cwdz.createDirPath(self.iozz, dirn); try cwdz.rename(oldp, cwdz, newp, self.iozz); }
fn delzRaws(self: *Loca, aren: std.mem.Allocator, item: Item) !void { try std.Io.Dir.cwd().deleteFile(self.iozz, try std.fs.path.join(aren, &.{ self.dirz, CF.rawd, item.rela })); }
fn trasDays(self: *Loca, aren: std.mem.Allocator) ![][]const u8 { const trad = try std.fs.path.join(aren, &.{ self.dirz, CF.tras }); var dirx = std.Io.Dir.cwd().openDir(self.iozz, trad, .{ .iterate = true }) catch return &.{}; defer dirx.close(self.iozz); var iter = dirx.iterate(); var list: std.ArrayList([]const u8) = .empty; while (try iter.next(self.iozz)) |entr| { if (entr.kind == .directory) try list.append(aren, try aren.dupe(u8, entr.name)); } return list.toOwnedSlice(aren); }
fn trasFree(self: *Loca, aren: std.mem.Allocator, nowz: i64, allz: bool, rslt: *Lres) !void { const days = try trasDays(self, aren); const cutz = nowz - @as(i64, self.conf.purg_tras_days) * CF.dayz; for (days) |name| { const dtzz = civi.civiPars(name) orelse continue; if (!allz and dtzz > cutz) continue; const pthz = try std.fs.path.join(aren, &.{ self.dirz, CF.tras, name }); const sizz = try locaUsed(aren, self.iozz, pthz); rslt.tras += 1; rslt.byts += sizz; if (!self.dryz) std.Io.Dir.cwd().deleteTree(self.iozz, pthz) catch {}; } }
fn housCall(self: *Loca, sqlz: [:0]const u8, cutz: i64) !u32 { if (self.dryz) { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); try stmt.bindIntz(1, cutz); _ = try stmt.step(); return @intCast(@max(stmt.colzIntz(0), 0)); } var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); try stmt.bindIntz(1, cutz); _ = try stmt.step(); return @intCast(self.dbzz.cha2()); }
fn housRows(self: *Loca, nowz: i64, rslt: *Lres) !void { const conf = self.conf; const logq: [:0]const u8 = if (self.dryz) "SELECT count(*) FROM logz WHERE timz<?1;" else "DELETE FROM logz WHERE timz<?1;"; const outq: [:0]const u8 = if (self.dryz) "SELECT count(*) FROM outb WHERE stat=1 AND timz<?1;" else "DELETE FROM outb WHERE stat=1 AND timz<?1;"; const deaq: [:0]const u8 = if (self.dryz) "SELECT count(*) FROM fron WHERE stat=2 AND addz<?1;" else "DELETE FROM fron WHERE stat=2 AND addz<?1;"; rslt.logz = try housCall(self, logq, nowz - @as(i64, conf.purg_logz_days) * CF.dayz); rslt.outb = try housCall(self, outq, nowz - @as(i64, conf.purg_outb_days) * CF.dayz); rslt.dead = try housCall(self, deaq, nowz - @as(i64, conf.purg_dead_days) * CF.dayz); }
pub fn locaRunz(self: *Loca, aren: std.mem.Allocator, nowz: i64) !Lres { var rslt: Lres = .{ .plan = self.dryz }; const capb: u64 = if (self.capz > 0) self.capz else @as(u64, self.conf.capz_disk_gbyt) * CF.gibi; rslt.cap2 = capb; try trasFree(self, aren, nowz, false, &rslt); const list = try scanRaws(self, aren); const agez = @as(i64, self.conf.purg_loca_days) * CF.dayz; var gonz = try aren.alloc(bool, list.len); @memset(gonz, false); for (list, 0..) |item, indx| { if (nowz - item.mtim < agez or !try iszzSafe(self, item.hexz)) continue; if (!self.dryz) try moveTras(self, aren, item, nowz); gonz[indx] = true; rslt.aged += 1; rslt.byts += item.size; }
var used = try locaUsed(aren, self.iozz, self.dirz); const high = capb * self.conf.purg_high_pctz / 100; const lowz = capb * self.conf.purg_lowz_pctz / 100; if (used >= high) { try trasFree(self, aren, nowz, true, &rslt); used = try locaUsed(aren, self.iozz, self.dirz); for (list, 0..) |item, indx| { if (used <= lowz) break; if (gonz[indx] or !try iszzSafe(self, item.hexz)) continue; if (!self.dryz) { delzRaws(self, aren, item) catch continue; used -|= item.size; } rslt.pres += 1; rslt.byts += item.size; gonz[indx] = true; } if (used >= high and !self.dryz) rslt.act2 = .stuck; if (self.dryz) rslt.act2 = if (rslt.pres > 0) .pruned else .stuck; } if (rslt.act2 == .none and (rslt.aged > 0 or rslt.pres > 0 or rslt.tras > 0)) rslt.act2 = .pruned; try housRows(self, nowz, &rslt); rslt.used = if (self.dryz) used else try locaUsed(aren, self.iozz, self.dirz); return rslt; }
